column723:
def segmented_sieve(n):
    import math
    limit = int(math.sqrt(n)) + 1
    primes = []
    sieve = [True] * limit
    for i in range(2, limit):
        if sieve[i]:
            primes.append(i)
            for j in range(i*i, limit, i):
                sieve[j] = False
    return primes[:10]
print(segmented_sieve(30))

column63:
def fibonacci(n):
    a, b = 0, 1
    for _ in range(n):
        yield b
        a, b = b, a + b
print(list(fibonacci(10)))

column159:
def fib_iterative(n):
    a, b = 0, 1
    for _ in range(n):
        yield b
        a, b = b, a + b
print(list(fib_iterative(10)))

