column321:
def factorial(n):
    if n == 0:
        return 1
    else:
        return n * factorial(n-1)
print([factorial(i) for i in range(10)])

column171:
def lucas(n):
    if n == 0:
        return 2
    elif n == 1:
        return 1
    else:
        a, b = 2, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b
print([lucas(i) for i in range(10)])

def pell(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, 2 * b + a
        return b
print([pell(i) for i in range(10)])

